/*
 * Validate that emul_bmi160_get_reg_value() rejects a read that would
 * start (or extend) one byte past the end of the emulator's register
 * file, rather than reading adjacent memory.
 */
ZTEST(sensing_tests, test_bmi160_emul_get_reg_value_oob)
{
	const struct emul *bmi160_emul = EMUL_DT_GET(DT_NODELABEL(bmi160_i2c));
	uint8_t out[2];
	int ret;

	zassert_not_null(bmi160_emul, "BMI160 I2C emulator not found");

	/* A read that starts at the last valid register and extends past the end */
	ret = emul_bmi160_get_reg_value(bmi160_emul, BMI160_REG_COUNT - 1, out, 2);
	zassert_equal(ret, -EIO,
		      "expected -EIO reading past the register file, got %d", ret);
}
